using System.Drawing;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.CatalogTools;
public sealed class SettingsForm:Form{readonly AppSettings s=SettingsService.Load();readonly Dictionary<string,TextBox> boxes=new();public SettingsForm(){Text="LSE Catalog Tools Settings";StartPosition=FormStartPosition.CenterParent;Size=new Size(1100,540);var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Padding=new Padding(12),AutoScroll=true};p.ColumnStyles.Add(new(SizeType.Absolute,330));p.ColumnStyles.Add(new(SizeType.Percent,100));p.ColumnStyles.Add(new(SizeType.Absolute,100));int r=0;Add(p,"Catalog MDB",nameof(s.CatalogPath),s.CatalogPath,r++,true);Add(p,"Company Standards JSON",nameof(s.CompanyStandardsPath),s.CompanyStandardsPath,r++,true);Add(p,"LSE part attribute",nameof(s.LsePartAttribute),s.LsePartAttribute,r++);Add(p,"Vault Explorer folder (auto-discovered when blank or wrong)",nameof(s.VaultExplorerPath),s.VaultExplorerPath,r++,true);Add(p,"Vault server",nameof(s.VaultServer),s.VaultServer,r++);Add(p,"Vault name",nameof(s.VaultName),s.VaultName,r++);Add(p,"Catalog Vault path ($/folder/.../default_cat.mdb; blank = no Vault)",nameof(s.CatalogVaultPath),s.CatalogVaultPath,r++);var save=new Button{Text="Save",Dock=DockStyle.Fill};save.Click+=(_,_)=>{s.CatalogPath=boxes[nameof(s.CatalogPath)].Text;s.CompanyStandardsPath=boxes[nameof(s.CompanyStandardsPath)].Text;s.LsePartAttribute=boxes[nameof(s.LsePartAttribute)].Text;s.VaultExplorerPath=boxes[nameof(s.VaultExplorerPath)].Text;s.VaultServer=boxes[nameof(s.VaultServer)].Text;s.VaultName=boxes[nameof(s.VaultName)].Text;s.CatalogVaultPath=boxes[nameof(s.CatalogVaultPath)].Text;SettingsService.Save(s);DialogResult=DialogResult.OK;Close();};p.Controls.Add(save,2,r);var test=new Button{Text="Test Vault",Dock=DockStyle.Fill};test.Click+=(_,_)=>{var c=new AppSettings();c.CatalogPath=boxes[nameof(s.CatalogPath)].Text;c.CompanyStandardsPath=boxes[nameof(s.CompanyStandardsPath)].Text;c.LsePartAttribute=boxes[nameof(s.LsePartAttribute)].Text;c.VaultExplorerPath=boxes[nameof(s.VaultExplorerPath)].Text;c.VaultServer=boxes[nameof(s.VaultServer)].Text;c.VaultName=boxes[nameof(s.VaultName)].Text;c.CatalogVaultPath=boxes[nameof(s.CatalogVaultPath)].Text;string rep;try{Cursor=Cursors.WaitCursor;rep=VaultCatalogService.TestReport(c);}finally{Cursor=Cursors.Default;}using var f=new TextReportForm("Vault test",rep);f.ShowDialog(this);};p.Controls.Add(test,1,r);Controls.Add(p);}
 void Add(TableLayoutPanel p,string label,string key,string value,int row,bool browse=false){p.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,row);var t=new TextBox{Text=value,Dock=DockStyle.Fill};boxes[key]=t;p.Controls.Add(t,1,row);if(browse){var b=new Button{Text="Browse",Dock=DockStyle.Fill};b.Click+=(_,_)=>{if(label.Contains("folder",StringComparison.OrdinalIgnoreCase)){using var f=new FolderBrowserDialog();if(f.ShowDialog()==DialogResult.OK)t.Text=f.SelectedPath;}else{using var f=new OpenFileDialog{Filter=label.Contains("JSON")?"JSON (*.json)|*.json":"Access (*.mdb)|*.mdb"};if(f.ShowDialog()==DialogResult.OK)t.Text=f.FileName;}};p.Controls.Add(b,2,row);}p.RowStyles.Add(new(SizeType.Absolute,48));}}
